public class FieldEntityController implements EntityController {

	private final FieldEnvironment fieldEnvironment;

	private final EntityHandlerRegistry handlerRegistry;


	public FieldEntityController(FieldEnvironment fieldEnvironment) {
		this(fieldEnvironment, EntityHandlerRegistry.shared());
	}


	public FieldEntityController(FieldEnvironment fieldEnvironment, EntityHandlerRegistry handlerRegistry) {
		this.fieldEnvironment = fieldEnvironment;
		this.handlerRegistry = handlerRegistry;
	}


	@Override
	public FieldEnvironment getFieldEnvironment() {
		return fieldEnvironment;
	}


	@Override
	public void place(Entity entity, Location location) {
		entity.updateLocation(location);
		handlerRegistry.resolve(entity).place(fieldEnvironment, entity, location);
	}


	@Override
	public void move(Entity entity, Location location) {
		Location currentLocation = entity.getLocation();
		if (currentLocation != null) {
			handlerRegistry.resolve(entity).clear(fieldEnvironment, currentLocation);
		}
		entity.updateLocation(location);
		handlerRegistry.resolve(entity).place(fieldEnvironment, entity, location);
	}


	@Override
	public void remove(Entity entity) {
		Location currentLocation = entity.getLocation();
		if (currentLocation != null) {
			handlerRegistry.resolve(entity).clear(fieldEnvironment, currentLocation);
			entity.updateLocation(null);
		}
	}
}

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import java.util.Set;
import java.util.stream.Collectors;
import java.util.stream.Stream;


public class Simulator {


	private static final int DEFAULT_WIDTH = 320;

	private static final int DEFAULT_DEPTH = 200;

	private static final TimeCycle DEFAULT_TIMECYCLE = TimeCycle.DAY;

	private static final Weather DEFAULT_WEATHER = Weather.SUN;

	private static final int TIMECYCLE_LENGTH = 4;


	private List<Animal> animals;

	private List<Plant> plants;

	private FieldEnvironment field;

	private EntityController entityController;

	private int step;

	private TimeCycle currentTimeCycle;

	private Climate climate;

	private FieldPopulator fieldPopulator;

	private final List<SimulationObserver> observers;

	private final FieldStats fieldStats;

	private Map<Class<?>, Integer> populationCounts;

	private int sickPercentage;


	public Simulator() {
		this(DEFAULT_DEPTH, DEFAULT_WIDTH);
		currentTimeCycle = DEFAULT_TIMECYCLE;
	}


	public Simulator(int depth, int width) {
		if (width <= 0 || depth <= 0) {
			System.out.println("The dimensions must be greater than zero.");
			System.out.println("Using default values.");
			depth = DEFAULT_DEPTH;
			width = DEFAULT_WIDTH;
		}


		animals = new ArrayList<>();

			plants = new ArrayList<>();
			observers = new ArrayList<>();
			fieldStats = new FieldStats();
			populationCounts = new LinkedHashMap<>();
			field = new Field(depth, width);
			entityController = new FieldEntityController(field);
			climate = new Climate(DEFAULT_WEATHER);
			fieldPopulator = new FieldPopulator();


		reset();
	}


	public void runLongSimulation() {
		simulate(4000);
	}


	public void simulate(int numSteps) {
		for (int step = 1; step <= numSteps && isViable(); step++) {
			simulateOneStep();
			delay(60);
		}
	}


	public void simulateOneStep() {
		Map<Class<?>, Integer> previousPopulation = populationCounts;
		step++;
		climate.updateClimate(step);

		plants.forEach(plant -> plant.increaseStage(climate));


		List<Animal> newAnimals = new ArrayList<>();
		animals.forEach(animal -> animal.act(newAnimals, currentTimeCycle));
		animals = Stream.concat(
				animals.stream().filter(Animal::isAlive),
				newAnimals.stream())
				.collect(Collectors.toCollection(ArrayList::new));


		if (step % TIMECYCLE_LENGTH == 0) {
			currentTimeCycle = currentTimeCycle.toggle();
		}

		notifyStepCompleted(previousPopulation);
	}


	public void reset() {
		Map<Class<?>, Integer> previousPopulation = populationCounts;
		step = 0;
		fieldPopulator.populate(entityController, animals, plants);
		currentTimeCycle = DEFAULT_TIMECYCLE;
		climate.setCurrentWeather(Weather.SUN);

		sickPercentage = 0;
		notifyReset(previousPopulation);
	}


	public void addObserver(SimulationObserver observer) {
		observers.add(observer);
		dispatchInitialEvents(observer);
	}


	public void removeObserver(SimulationObserver observer) {
		observers.remove(observer);
	}


	private void notifyReset(Map<Class<?>, Integer> previousPopulation) {
		sickPercentage = calculateSickPercentage();
		SimulationSnapshot snapshot = createSnapshot();
		populationCounts = calculatePopulationCounts();
		dispatchEvent(new SimulationResetEvent(snapshot));
		dispatchPopulationChangedEvent(snapshot, previousPopulation, populationCounts);
	}


	private void notifyStepCompleted(Map<Class<?>, Integer> previousPopulation) {
		sickPercentage = calculateSickPercentage();
		SimulationSnapshot snapshot = createSnapshot();
		populationCounts = calculatePopulationCounts();
		dispatchPopulationChangedEvent(snapshot, previousPopulation, populationCounts);
		dispatchEvent(new SimulationStepCompletedEvent(snapshot));
	}


	private int calculateSickPercentage() {
		if (animals.isEmpty()) {
			return 0;
		}

		long sickAnimals = animals.stream()
				.filter(Animal::isSick)
				.count();
		return (int) ((sickAnimals * 100) / animals.size());
	}


	private boolean isViable() {
		return fieldStats.isViable(field);
	}


	private Map<Class<?>, Integer> calculatePopulationCounts() {
		return field.streamAnimals()
				.collect(Collectors.groupingBy(Animal::getClass, LinkedHashMap::new, Collectors.summingInt(animal -> 1)));
	}


	private void dispatchPopulationChangedEvent(SimulationSnapshot snapshot, Map<Class<?>, Integer> previousPopulation,
			Map<Class<?>, Integer> currentPopulation) {
		if (!currentPopulation.equals(previousPopulation)) {
			dispatchEvent(new PopulationChangedEvent(snapshot, previousPopulation, currentPopulation));
		}
	}


	private void dispatchEvent(SimulationEvent event) {
		observers.stream()
				.filter(observer -> observer.supports(event))
				.forEach(observer -> observer.onSimulationEvent(event));
	}


	private void dispatchToObserver(SimulationObserver observer, SimulationEvent event) {
		if (observer.supports(event)) {
			observer.onSimulationEvent(event);
		}
	}


	private SimulationSnapshot createSnapshot() {
		return new SimulationSnapshot(step, currentTimeCycle, field, climate, sickPercentage, isViable());
	}


	private SimulationEvent createInitialEvent() {
		SimulationSnapshot snapshot = createSnapshot();
		if (step == 0) {
			return new SimulationResetEvent(snapshot);
		}
		return new SimulationStepCompletedEvent(snapshot);
	}


	private void dispatchInitialEvents(SimulationObserver observer) {
		SimulationSnapshot snapshot = createSnapshot();
		dispatchToObserver(observer, createInitialEvent());
		if (!populationCounts.isEmpty()) {
			dispatchToObserver(observer, new PopulationChangedEvent(snapshot, Map.of(), populationCounts));
		}
	}


	private void delay(int millisec) {
		try {
			Thread.sleep(millisec);
		} catch (InterruptedException ie) {

		}
	}
}

import java.util.ArrayList;
import java.util.List;
import java.util.stream.Stream;


public class FieldPopulator {

	private static final double FLOWER_CREATION_PROBABILITY = 0.07;

	private static final double MOUSE_CREATION_PROBABILITY = 0.07;

	private static final double DUCK_CREATION_PROBABILITY = 0.07;

	private static final double BIRD_CREATION_PROBABILITY = 0.07;

	private static final double WOLF_CREATION_PROBABILITY = 0.03;

	private static final double BEAR_CREATION_PROBABILITY = 0.03;

	private final RandomService random;

	private final List<AnimalSpawnRule> animalSpawnRules;


	public FieldPopulator() {
		this.random = RandomService.shared();
		this.animalSpawnRules = new ArrayList<>();
		registerAnimalSpawnRules();
	}


	public void populate(EntityController controller, List<Animal> animals, List<Plant> plants) {
		FieldEnvironment field = controller.getFieldEnvironment();
		field.clear();
		animals.clear();
		plants.clear();

		field.streamLocations().forEach(location -> populateLocation(controller, location, animals, plants));
	}


	private Plant createPlant(EntityController controller, Location location) {
		if (random.chance(FLOWER_CREATION_PROBABILITY)) {
			return new Flower(controller, location);
		}
		return new Grass(controller, location);
	}


	private Animal createAnimal(EntityController controller, Location location) {
		return animalSpawnRules.stream()
				.filter(rule -> rule.shouldSpawn(random))
				.findFirst()
				.map(rule -> rule.createAnimal(controller, location))
				.orElse(null);
	}


	private void registerAnimalSpawnRules() {
		Stream.of(
				new AnimalSpawnRule(BIRD_CREATION_PROBABILITY, Bird::new),
				new AnimalSpawnRule(MOUSE_CREATION_PROBABILITY, Mouse::new),
				new AnimalSpawnRule(DUCK_CREATION_PROBABILITY, Duck::new),
				new AnimalSpawnRule(WOLF_CREATION_PROBABILITY, Wolf::new),
				new AnimalSpawnRule(BEAR_CREATION_PROBABILITY, Bear::new))
				.forEach(animalSpawnRules::add);
	}


	private void populateLocation(EntityController controller, Location location, List<Animal> animals, List<Plant> plants) {
		plants.add(createPlant(controller, location));

		Animal animal = createAnimal(controller, location);
		if (animal != null) {
			animals.add(animal);
		}
	}


	private static class AnimalSpawnRule {
		private final double spawnProbability;

		private final AnimalFactory animalFactory;


		private AnimalSpawnRule(double spawnProbability, AnimalFactory animalFactory) {
			this.spawnProbability = spawnProbability;
			this.animalFactory = animalFactory;
		}


		private boolean shouldSpawn(RandomService random) {
			return random.chance(spawnProbability);
		}


		private Animal createAnimal(EntityController controller, Location location) {
			return animalFactory.create(true, controller, location);
		}
	}
}

